package com.smartinternship.controller; import com.smartinternship.model.Student; import com.smartinternship.repository.StudentRepository; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/students") public class StudentController { private final StudentRepository r; public StudentController(StudentRepository r){this.r=r;} @GetMapping public List<Student> all(){return r.findAll();} @PostMapping @ResponseStatus(HttpStatus.CREATED) public Student create(@Valid @RequestBody Student s){return r.save(s);} @GetMapping("/{id}") public Student one(@PathVariable Long id){return r.findById(id).orElseThrow();} }